using System.Net.Http;
using System.Threading.Tasks;
using Bizuit.Backend.Abstractions;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Http.Resilience;
using Polly;
namespace Demo.Plugin
{
    public class DemoBackendPlugin : IBackendPlugin
    {
        public void ConfigureServices(IServiceCollection services, IConfiguration configuration)
        {
            services.AddHttpClient<PacaraClient>()
                .AddStandardResilienceHandler(options =>
                {
                    options.Retry.MaxRetryAttempts = 2;
                    options.Retry.UseJitter = true;
                    options.Retry.ShouldHandle = args =>
                    {
                        var metodo = args.Context.GetRequestMessage()?.Method;
                        if (metodo is not null && metodo != HttpMethod.Get)
                            return ValueTask.FromResult(false);
                        return ValueTask.FromResult(HttpClientResiliencePredicates.IsTransient(args.Outcome));
                    };
                });
        }
    }
    public class PacaraClient
    {
        private readonly HttpClient _http;
        public PacaraClient(HttpClient http) { _http = http; }
        public Task<HttpResponseMessage> GetAsync(string path, System.Threading.CancellationToken ct) => _http.GetAsync(path, ct);
    }
}

using System.Net.Http;
using System.Threading.Tasks;
using Bizuit.Backend.Abstractions;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Http.Resilience;
using Polly;
namespace Demo.Plugin
{
    public class DemoBackendPlugin : IBackendPlugin
    {
        public void ConfigureServices(IServiceCollection services, IConfiguration configuration)
        {
            // El host carga SU Http.Resilience: nada estático de la librería dentro del predicado.
            var claveRequest = new ResiliencePropertyKey<HttpRequestMessage>("Resilience.Http.RequestMessage");
            services.AddHttpClient<PacaraClient>()
                .AddStandardResilienceHandler(options =>
                {
                    options.Retry.MaxRetryAttempts = 2;
                    options.Retry.UseJitter = true;
                    var esTransitorio = options.Retry.ShouldHandle;
                    options.Retry.ShouldHandle = async args =>
                    {
                        var metodo = (args.Context.Properties.TryGetValue(claveRequest, out var req) ? req : null)?.Method
                                     ?? args.Outcome.Result?.RequestMessage?.Method;
                        if (metodo is null || metodo != HttpMethod.Get) return false;
                        return await esTransitorio(args);
                    };
                });
        }
    }
    public class PacaraClient
    {
        private readonly HttpClient _http;
        public PacaraClient(HttpClient http) { _http = http; }
        public Task<HttpResponseMessage> GetAsync(string path, System.Threading.CancellationToken ct) => _http.GetAsync(path, ct);
    }
}
